<?php require 'includes/auth.php'; $cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll(); $q=trim($_GET['q']??''); $cat=(int)($_GET['cat']??0); $sql="SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1"; $a=[]; if($q!==''){ $sql.=" AND (p.name LIKE ? OR p.sku LIKE ?)"; $a=["%$q%","%$q%"]; } if($cat){$sql.=" AND p.category_id=?";$a[]=$cat;} $sql.=" ORDER BY p.id DESC"; $st=$pdo->prepare($sql);$st->execute($a);$products=$st->fetchAll(); ?>
